60	func TestCreateIdempotenceAndConflict(t *testing.T) {
61		s := openTestStore(t)
62		c := Circuit{Name: "transfer", Version: 3, Constraints: 2048, PublicInputs: 2, PrivateInputs: 4, Description: "d3"}
63	
64		first, err := s.CreateCircuit(c)
65		if err != nil {
66			t.Fatal(err)
67		}
68		if first.Frozen {
69			t.Fatal("new circuit must be a draft")
70		}
71		// Same name+version with the identical description returns the stored
72		// record, regardless of the other (ignored-on-existing) count arguments.
73		same := Circuit{Name: "transfer", Version: 3, Constraints: 9999, PublicInputs: 9, PrivateInputs: 9, Description: "d3"}
74		got, err := s.CreateCircuit(same)
75		if err != nil {
76			t.Fatalf("identical re-create: %v", err)
77		}
78		if got.Constraints != 2048 || got.PublicInputs != 2 || got.PrivateInputs != 4 || got.Frozen {
79			t.Fatalf("re-create altered stored record: %+v", got)
80		}
81		// Different description is a conflict and changes nothing.
82		conflict := c
83		conflict.Description = "different"
84		if _, err := s.CreateCircuit(conflict); !errors.Is(err, ErrConflict) {
85			t.Fatalf("want conflict, got %v", err)
86		}
87		got, err = s.GetCircuit("transfer", 3)
88		if err != nil {
89			t.Fatal(err)
90		}
91		if got.Description != "d3" {
92			t.Fatalf("conflicting create mutated description: %q", got.Description)
93		}
94	
95		// Multiple versions of the same name coexist.
96		v4 := Circuit{Name: "transfer", Version: 4, Constraints: 4096, Description: "d4"}
97		if _, err := s.CreateCircuit(v4); err != nil {
98			t.Fatal(err)
99		}
100		got, err = s.GetCircuit("transfer", 3)
101		if err != nil || got.Version != 3 {
102			t.Fatalf("v3 displaced by v4: %+v %v", got, err)
103		}
104	}
