160	func TestSetupScopedToFrozenVersion(t *testing.T) {
161		s := openTestStore(t)
162		mk := func(name string, v int, frozen bool) {
163			t.Helper()
164			if _, err := s.CreateCircuit(Circuit{Name: name, Version: v, Constraints: 64, Description: fmt.Sprintf("%s%d", name, v)}); err != nil {
165				t.Fatal(err)
166			}
167			if frozen {
168				if _, err := s.FreezeCircuit(name, v); err != nil {
169					t.Fatal(err)
170				}
171			}
172		}
173	
174		if _, err := s.RecordSetup("ghost", 1); !errors.Is(err, ErrNotFound) {
175			t.Fatalf("want not found, got %v", err)
176		}
177		mk("c", 1, false)
178		if _, err := s.RecordSetup("c", 1); !errors.Is(err, ErrNotFrozen) {
179			t.Fatalf("want not frozen, got %v", err)
180		}
181		if _, err := s.FreezeCircuit("c", 1); err != nil {
182			t.Fatal(err)
183		}
184		if _, err := s.RecordSetup("c", 1); err != nil {
185			t.Fatalf("record setup: %v", err)
186		}
187		// Idempotent: repeat registration is harmless.
188		if _, err := s.RecordSetup("c", 1); err != nil {
189			t.Fatalf("repeat setup: %v", err)
190		}
191		if setup, found, err := s.GetSetup("c", 1); err != nil || !found || setup.Version != 1 {
192			t.Fatalf("get setup: %+v found=%v err=%v", setup, found, err)
193		}
194		if before := countSetups(t, s); before != 1 {
195			t.Fatalf("want 1 setup record, got %d", before)
196		}
197		// A sibling frozen version cannot borrow the setup.
198		mk("c", 2, true)
199		if _, err := s.SubmitJob(Job{ID: "jv2", Circuit: "c", Version: 2, Kind: "prove", Attempt: 1}); !errors.Is(err, ErrSetupMissing) {
200			t.Fatalf("want setup missing for v2, got %v", err)
201		}
202		if _, found, err := s.GetSetup("c", 2); err != nil || found {
203			t.Fatalf("v2 should have no setup, found=%v err=%v", found, err)
204		}
205		if _, err := s.RecordSetup("c", 2); err != nil {
206			t.Fatalf("record v2 setup: %v", err)
207		}
208		if got, err := s.SubmitJob(Job{ID: "jv2", Circuit: "c", Version: 2, Kind: "prove", Attempt: 1}); err != nil {
209			t.Fatalf("v2 job after its own setup: %v", got)
210		}
211		if countSetups(t, s) != 2 {
212			t.Fatalf("want 2 setups, got %d", countSetups(t, s))
213		}
214	}
