	// Rejected submissions left no jobs behind.
	for _, id := range []string{"jbad", "jborrow", "jbare"} {
		if _, err := s.GetJob(id); !errors.Is(err, ErrNotFound) {
			t.Fatalf("rejected job %q left a trace: %v", id, err)
		}
	}
