		mutate func(map[string]any)
	}{
		{"artifact removed", func(env map[string]any) { delete(env, "artifacts") }},
		{"artifact hash changed", func(env map[string]any) {
			arts := env["artifacts"].([]any)
			arts[0].(map[string]any)["hash"] = "deadbeef"
		}},
	}
