		t.Fatal(err)
	}

	code, _, errOut := r("job-get", "--dir", dir, "--id", "j1")
	if code != 3 || !strings.Contains(errOut, "read failed") {
		t.Fatalf("tampered binding: code=%d err=%q", code, errOut)
