	// not an artifact error: the duplicate check runs first.
	if _, err := s.SubmitJob(Job{ID: "j1", Circuit: "c", Version: 1, Kind: "prove", Attempt: 1, CompiledHash: "does-not-exist"}); !errors.Is(err, ErrConflict) {
