			if !bytes.Equal(after, tampered) {
				t.Fatal("failed open modified the data file")
			}

			// Restore the committed file for the next case.
			if err := os.WriteFile(dataFilePath(dir), raw, 0o644); err != nil {
				t.Fatal(err)
			}
		})
	}
}

